class Solution {
  public long maxRatings(int[][] units) {
    int m = units.length;
    long sumMin = 0, sumSecond = 0, minRating = Long.MAX_VALUE, minSecond = Long.MAX_VALUE;
    for (int[] device : units) {
      long min = Long.MAX_VALUE, second = Long.MAX_VALUE;
      for (int u : device) {
        if (u < min) {
          second = min;
          min = u;
        } else if (u < second) second = u;
      }
      if (second == Long.MAX_VALUE) second = 0;
      sumMin += min;
      sumSecond += second;
      minRating = Math.min(minRating, min);
      minSecond = Math.min(minSecond, second);
    }
    if (m == 1) return sumMin;
    return Math.max(sumMin, sumSecond - minSecond + minRating);
  }
}
